                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="ielts-listening-question-item"> • <span>Jack</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">24</strong><select data-qnum="24" name="question_24" class="ielts-inline-select"><option value="">[ 24 ] Tanlang...</option><option value="A. demonstrated independence">A. demonstrated independence</option><option value="B. asked for teacher support">B. asked for teacher support</option><option value="C. developed a competitive attitude">C. developed a competitive attitude</option><option value="D. seemed to find the activity calming">D. seemed to find the activity calming</option><option value="E. seemed pleased with the results">E. seemed pleased with the results</option><option value="F. seemed confused">F. seemed confused</option><option value="G. seemed to find the activity easy">G. seemed to find the activity easy</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="ielts-listening-question-item"> • <span>Naomi</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">25</strong><select data-qnum="25" name="question_25" class="ielts-inline-select"><option value="">[ 25 ] Tanlang...</option><option value="A. demonstrated independence">A. demonstrated independence</option><option value="B. asked for teacher support">B. asked for teacher support</option><option value="C. developed a competitive attitude">C. developed a competitive attitude</option><option value="D. seemed to find the activity calming">D. seemed to find the activity calming</option><option value="E. seemed pleased with the results">E. seemed pleased with the results</option><option value="F. seemed confused">F. seemed confused</option><option value="G. seemed to find the activity easy">G. seemed to find the activity easy</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="ielts-listening-question-item"> • <span>Anya</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">26</strong><select data-qnum="26" name="question_26" class="ielts-inline-select"><option value="">[ 26 ] Tanlang...</option><option value="A. demonstrated independence">A. demonstrated independence</option><option value="B. asked for teacher support">B. asked for teacher support</option><option value="C. developed a competitive attitude">C. developed a competitive attitude</option><option value="D. seemed to find the activity calming">D. seemed to find the activity calming</option><option value="E. seemed pleased with the results">E. seemed pleased with the results</option><option value="F. seemed confused">F. seemed confused</option><option value="G. seemed to find the activity easy">G. seemed to find the activity easy</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="ielts-listening-question-item"> • <span>Zara</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">27</strong><select data-qnum="27" name="question_27" class="ielts-inline-select"><option value="">[ 27 ] Tanlang...</option><option value="A. demonstrated independence">A. demonstrated independence</option><option value="B. asked for teacher support">B. asked for teacher support</option><option value="C. developed a competitive attitude">C. developed a competitive attitude</option><option value="D. seemed to find the activity calming">D. seemed to find the activity calming</option><option value="E. seemed pleased with the results">E. seemed pleased with the results</option><option value="F. seemed confused">F. seemed confused</option><option value="G. seemed to find the activity easy">G. seemed to find the activity easy</option></select></span></div></div>                                                                        <div class="options-dnd-panel dnd-panel dnd-panel--matching" data-dnd-group="14634">
                                                                            <div class="dnd-panel-instruction">Drag and drop an option to fill in each blank.</div>
                                                                            <div class="dnd-cards-container">
                                                                                                                                                                    <div class="dnd-card" draggable="true" data-value="A" data-text="A. demonstrated independence">
                                                                                        <span class="dnd-label">A.</span>
                                                                                        <span class="dnd-text">demonstrated independence</span>
                                                                                    </div>
                                                                                                                                                                    <div class="dnd-card" draggable="true" data-value="B" data-text="B. asked for teacher support">
                                                                                        <span class="dnd-label">B.</span>
                                                                                        <span class="dnd-text">asked for teacher support</span>
                                                                                    </div>
                                                                                                                                                                    <div class="dnd-card" draggable="true" data-value="C" data-text="C. developed a competitive attitude">
                                                                                        <span class="dnd-label">C.</span>
                                                                                        <span class="dnd-text">developed a competitive attitude</span>
                                                                                    </div>
                                                                                                                                                                    <div class="dnd-card" draggable="true" data-value="D" data-text="D. seemed to find the activity calming">
                                                                                        <span class="dnd-label">D.</span>
